```java
package com.acme.billing;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class BillingExceptionHandler {

    @ExceptionHandler(InvoiceNotFoundException.class)
    public ResponseEntity<ApiResponse<Void>> handleNotFound(InvoiceNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(ApiResponse.error(new ApiError("INVOICE_NOT_FOUND", ex.getMessage())));
    }

    @ExceptionHandler(InvoiceAccessDeniedException.class)
    public ResponseEntity<ApiResponse<Void>> handleAccessDenied(InvoiceAccessDeniedException ex) {
        return ResponseEntity.status(HttpStatus.FORBIDDEN)
                .body(ApiResponse.error(new ApiError("INVOICE_ACCESS_DENIED", ex.getMessage())));
    }

    @ExceptionHandler(InvoiceNotCancellableException.class)
    public ResponseEntity<ApiResponse<Void>> handleNotCancellable(InvoiceNotCancellableException ex) {
        return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(ApiResponse.error(new ApiError("INVOICE_NOT_CANCELLABLE", ex.getMessage())));
    }
}
```

```java
package com.acme.billing;

import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/invoices")
public class InvoiceController {

    private final InvoiceCancellationService invoiceCancellationService;

    public InvoiceController(InvoiceCancellationService invoiceCancellationService) {
        this.invoiceCancellationService = invoiceCancellationService;
    }

    @PostMapping("/{id}/cancel")
    public ApiResponse<Void> cancel(@PathVariable("id") long invoiceId,
                                     @AuthenticationPrincipal Long customerId) {
        invoiceCancellationService.cancelInvoice(invoiceId, customerId);
        return ApiResponse.ok(null);
    }
}
```

Convention decisions applied: constructor injection (no Lombok/field injection), authorization/state rule enforced in the service rather than relying only on route-level security ("two locks on the door"), and failures surfaced as domain exceptions mapped by a `@RestControllerAdvice` to `ApiResponse.error(...)` instead of try/catch in the controller. I invented `InvoiceStatus` and how `customerId` is resolved (`@AuthenticationPrincipal Long`) since those weren't specified — swap that resolution for whatever your security setup actually provides.

